v16_source = json.loads(zlib.decompress(_v16_bytes).decode('utf-8'))
v16_E = pd.DataFrame(v16_source['energy'])
v16_R = pd.DataFrame(v16_source['ranks'])
v16_T = pd.DataFrame(v16_source['transfer'])
# Localize only source-category labels; numerical observations are unchanged.
assert v16_T['group'].isin(['Same instrument type', 'Different instrument types']).all()
v16_case = v16_source['case']
v16_full = v16_source['full']
assert len(v16_E)==221 and len(v16_R)==274 and len(v16_T)==323

# Unified dark visual design; accent colors emphasize measured findings.
VBG='#0F192C'; VAX='#13243A'; VTXT='#EAF3FC'; VMUT='#B1C6D9'
VAQUA='#59DFCD'; VBLUE='#88B8F8'; VCORAL='#FF9E91'; VGOLD='#F5CC89'

def v16_axes(fig, axes):
    fig.patch.set_facecolor(VBG)
    for ax in np.ravel(np.asarray(axes)):
        ax.set_facecolor(VAX)
        for spine in ax.spines.values(): spine.set_color('#344E67')
        ax.tick_params(colors=VMUT,labelsize=10)
        ax.xaxis.label.set_color(VMUT)
        ax.yaxis.label.set_color(VMUT)
        ax.title.set_color(VTXT)
        ax.grid(axis='y',color='#314962',alpha=.4,linewidth=.7)
        ax.set_axisbelow(True)
    return fig

def v16_caption(text):
    display(HTML('<div style="background:#13273E;border:1px solid #31556D;'
      'border-left:4px solid #59DFCD;padding:14px 17px;border-radius:9px;'
      'color:#D7E8F4;font-size:13px;line-height:1.7;max-width:970px;">'
      +text+'</div>'))
